from copy import deepcopy
from html.parser import HTMLParser
from posixpath import basename
from urllib.parse import urljoin, urlparse


class _EntryFinder(HTMLParser):
    def __init__(self):
        super().__init__()
        self.src = None

    def handle_starttag(self, tag, attrs):
        if self.src is not None or tag.lower() != "script":
            return
        attributes = dict(attrs)
        src = attributes.get("src")
        if attributes.get("data-kind") == "entry" and src:
            if urlparse(src).path.endswith(".mjs"):
                self.src = src


def stage_module(markup, page_url, cache, available):
    if not isinstance(markup, str) or not isinstance(page_url, str):
        raise TypeError("markup and page_url must be strings")

    finder = _EntryFinder()
    finder.feed(markup)
    finder.close()
    result_cache = deepcopy(dict(cache))

    if finder.src is None:
        return {
            "url": None,
            "filename": None,
            "source": None,
            "downloaded": False,
            "cache": result_cache,
        }

    url = urljoin(page_url, finder.src)
    filename = basename(urlparse(url).path)
    if filename in result_cache:
        source = result_cache[filename]
        downloaded = False
    else:
        source = deepcopy(available[url])
